"""사용자 auto-generated file 을 id 로 읽기: 하나 읽기, 여러 개 한 번에 읽기."""

from __future__ import annotations

from dataclasses import dataclass
from datetime import UTC, datetime
from typing import override

import pytest

from ai.backend.common.data.entity.auto_generated_file import AutoGeneratedFileID
from ai.backend.common.dto.manager.v2.auto_generated_file.response import AutoGeneratedFileNode
from ai.backend.common.dto.manager.v2.auto_generated_file.types import (
    AutoGeneratedFileScopeType,
)
from ai.backend.manager.api.adapters.auto_generated_file.adapter import AutoGeneratedFileAdapter
from ai.backend.manager.data.permission.types import Permission
from ai.backend.manager.errors.permission import NotEnoughPermission
from ai.backend.manager.models.utils import ExtendedAsyncSAEngine
from ai.backend.testutils.scenario_steps import (
    Answered,
    Given,
    Held,
    Refused,
    Same,
    SameAs,
    Says,
    Scenario,
    Then,
    Verdict,
    When,
)
from bai_scenario.components.answers import MissingResponse, TheCallIsRefused
from bai_scenario.components.auto_generated_file import (
    A_FILE_NOT_DEFAULT,
    CONFIG_PATH,
    AUserAndTheirOwnConfig,
    SomeoneWithTheirOwnConfig,
)
from bai_scenario.components.domain import WrittenByThisRun
from bai_scenario.runner.acting import ActingAs
from bai_scenario.runner.planting import TestSeedingSession
from bai_scenario.runner.steps import run_scenario

type Laid = AUserAndTheirOwnConfig
type Answer = AutoGeneratedFileNode | list[AutoGeneratedFileNode | Exception | None]
type ReadingStep = Scenario[TestSeedingSession, Laid, AutoGeneratedFileAdapter, Answer]

THE_SEEDED_FILE = Says(
    f"심어 둔 {CONFIG_PATH} auto-generated file 의 id",
    english=f"the id of the {CONFIG_PATH} auto-generated file seeded",
)
THE_OWNER = Says("파일 주인의 id", english="the owner's id")


# --- When ---


@dataclass(frozen=True)
class Getting(When[Laid, AutoGeneratedFileAdapter, Answer]):
    """심은 파일 하나를 id 로 읽는다."""

    @override
    def operation(self) -> str:
        return "get"

    @override
    def describe(self, laid: Laid) -> str:
        return Says(
            f"{laid.owner.username}이 자기 {CONFIG_PATH} auto-generated file 을 id 로 읽습니다",
            english=f"{laid.owner.username} reads their {CONFIG_PATH} auto-generated file by id",
        )

    @override
    async def call(self, adapter: AutoGeneratedFileAdapter, laid: Laid) -> Answer:
        with ActingAs(laid.owner):
            payload = await adapter.get(AutoGeneratedFileID(laid.files[0].id))
        return payload.auto_generated_file


@dataclass(frozen=True)
class LoadingById(When[Laid, AutoGeneratedFileAdapter, Answer]):
    """심은 파일 id 하나만 준다."""

    @override
    def operation(self) -> str:
        return "bulk_get_ids"

    @override
    def describe(self, laid: Laid) -> str:
        return Says(
            f"{laid.owner.username}이 자기 {CONFIG_PATH} auto-generated file 을 id 로 일괄 "
            "조회합니다",
            english=(
                f"{laid.owner.username} loads their {CONFIG_PATH} auto-generated file by id in "
                "one call"
            ),
        )

    @override
    async def call(self, adapter: AutoGeneratedFileAdapter, laid: Laid) -> Answer:
        with ActingAs(laid.owner):
            return await adapter.bulk_get_ids([AutoGeneratedFileID(laid.files[0].id)])


# --- Then ---


@dataclass(frozen=True)
class TheSeededFile(Then[Laid, Answer]):
    started: datetime

    @override
    def says(self) -> str:
        return Says("심어 둔 파일이 응답으로 옵니다", english="the file seeded comes back")

    @override
    def look(self, laid: Laid, answered: Answered[Answer]) -> list[Verdict]:
        node = answered.response
        if not isinstance(node, AutoGeneratedFileNode):
            return [MissingResponse(answered.raised)]
        return [
            Held("id", node.id, SameAs(laid.files[0].id, THE_SEEDED_FILE)),
            Held("entity_id", node.entity_id, SameAs(laid.files[0].id, THE_SEEDED_FILE)),
            Same("scope_type", str(node.scope_type), str(AutoGeneratedFileScopeType.USER)),
            Held("scope_id", node.scope_id, SameAs(laid.owner.id, THE_OWNER)),
            Same("path", node.path, CONFIG_PATH),
            Same("is_default", node.is_default, False),
            Held("created_at", node.created_at, WrittenByThisRun(self.started)),
            Held("updated_at", node.updated_at, WrittenByThisRun(self.started)),
        ]


@dataclass(frozen=True)
class TheSeededFileAlone(Then[Laid, Answer]):
    started: datetime

    @override
    def says(self) -> str:
        return Says("심어 둔 파일 하나가 응답으로 옵니다", english="the one file seeded comes back")

    @override
    def look(self, laid: Laid, answered: Answered[Answer]) -> list[Verdict]:
        loaded = answered.response
        if not isinstance(loaded, list):
            return [MissingResponse(answered.raised)]
        seen: list[Verdict] = [Same("length", len(loaded), 1)]
        first = loaded[0] if loaded else None
        if isinstance(first, AutoGeneratedFileNode):
            seen.extend(TheSeededFile(started=self.started).look(laid, Answered(response=first)))
        else:
            seen.append(Same("[0]", type(first).__name__, "AutoGeneratedFileNode"))
        return seen


@dataclass(frozen=True)
class ARefusalAlone(Then[Laid, Answer]):
    """호출은 성공하고, 그 자리는 권한 부족으로 거부된다."""

    @override
    def says(self) -> str:
        return Says(
            "그 항목은 권한 부족으로 거부됩니다",
            english="that entry is rejected for lack of permission",
        )

    @override
    def look(self, laid: Laid, answered: Answered[Answer]) -> list[Verdict]:
        loaded = answered.response
        if not isinstance(loaded, list):
            return [Refused(NotEnoughPermission, answered.raised)]
        first = loaded[0] if loaded else None
        return [
            Same("length", len(loaded), 1),
            Refused(NotEnoughPermission, first if isinstance(first, Exception) else None),
        ]


# --- Scenarios ---


@dataclass(frozen=True)
class AUserGetsTheirFile(Scenario[TestSeedingSession, Laid, AutoGeneratedFileAdapter, Answer]):
    started: datetime

    @override
    def summary(self) -> str:
        return "a-user-granted-read-gets-an-auto-generated-file"

    @override
    def describe(self) -> str:
        return Says(
            "READ 를 받은 사용자가 자기 auto-generated file 을 id 로 읽으면, 그 파일이 응답으로 "
            "옵니다",
            english=(
                "when a user holding READ reads their auto-generated file by id, that file comes "
                "back"
            ),
        )

    @override
    def given(self) -> Given[TestSeedingSession, Laid]:
        return SomeoneWithTheirOwnConfig(
            permissions=(Permission.READ,), files=(A_FILE_NOT_DEFAULT,)
        )

    @override
    def when(self) -> When[Laid, AutoGeneratedFileAdapter, Answer]:
        return Getting()

    @override
    def then(self) -> Then[Laid, Answer]:
        return TheSeededFile(started=self.started)


@dataclass(frozen=True)
class AUserGrantedNothingMayNotGet(
    Scenario[TestSeedingSession, Laid, AutoGeneratedFileAdapter, Answer]
):
    @override
    def summary(self) -> str:
        return "a-user-granted-nothing-may-not-get-an-auto-generated-file"

    @override
    def describe(self) -> str:
        return Says(
            "권한을 받지 않은 사용자가 자기 auto-generated file 을 id 로 읽으려 하면, 권한 부족으로 "
            "거부됩니다",
            english=(
                "a user holding no permission who tries to read their auto-generated file by id "
                "is rejected for lack of permission"
            ),
        )

    @override
    def given(self) -> Given[TestSeedingSession, Laid]:
        return SomeoneWithTheirOwnConfig(files=(A_FILE_NOT_DEFAULT,))

    @override
    def when(self) -> When[Laid, AutoGeneratedFileAdapter, Answer]:
        return Getting()

    @override
    def then(self) -> Then[Laid, Answer]:
        return TheCallIsRefused(NotEnoughPermission)


@dataclass(frozen=True)
class AUserLoadsTheirFile(Scenario[TestSeedingSession, Laid, AutoGeneratedFileAdapter, Answer]):
    started: datetime

    @override
    def summary(self) -> str:
        return "a-user-granted-read-loads-an-auto-generated-file-by-id"

    @override
    def describe(self) -> str:
        return Says(
            "READ 를 받은 사용자가 자기 auto-generated file 을 id 로 일괄 조회하면, 그 파일이 "
            "응답으로 옵니다",
            english=(
                "when a user holding READ loads their auto-generated file by id in one call, "
                "that file comes back"
            ),
        )

    @override
    def given(self) -> Given[TestSeedingSession, Laid]:
        return SomeoneWithTheirOwnConfig(
            permissions=(Permission.READ,), files=(A_FILE_NOT_DEFAULT,)
        )

    @override
    def when(self) -> When[Laid, AutoGeneratedFileAdapter, Answer]:
        return LoadingById()

    @override
    def then(self) -> Then[Laid, Answer]:
        return TheSeededFileAlone(started=self.started)


@dataclass(frozen=True)
class AUserGrantedNothingGetsARefusal(
    Scenario[TestSeedingSession, Laid, AutoGeneratedFileAdapter, Answer]
):
    @override
    def summary(self) -> str:
        return "a-user-granted-nothing-gets-a-rejection-for-an-auto-generated-file"

    @override
    def describe(self) -> str:
        return Says(
            "권한을 받지 않은 사용자가 자기 auto-generated file 을 id 로 일괄 조회하면, 호출은 "
            "성공하되 그 항목은 권한 부족으로 거부됩니다",
            english=(
                "when a user holding no permission loads their auto-generated file by id in one "
                "call, the call succeeds but that entry is rejected for lack of permission"
            ),
        )

    @override
    def given(self) -> Given[TestSeedingSession, Laid]:
        return SomeoneWithTheirOwnConfig(files=(A_FILE_NOT_DEFAULT,))

    @override
    def when(self) -> When[Laid, AutoGeneratedFileAdapter, Answer]:
        return LoadingById()

    @override
    def then(self) -> Then[Laid, Answer]:
        return ARefusalAlone()


SCENARIOS: list[ReadingStep] = [
    AUserGetsTheirFile(started=datetime.now(UTC)),
    AUserGrantedNothingMayNotGet(),
    AUserLoadsTheirFile(started=datetime.now(UTC)),
    AUserGrantedNothingGetsARefusal(),
]


@pytest.mark.parametrize("scenario", SCENARIOS, ids=lambda s: s.summary())
async def test_v2_reading(
    scenario: ReadingStep,
    auto_generated_file_adapter: AutoGeneratedFileAdapter,
    engine: ExtendedAsyncSAEngine,
) -> None:
    await run_scenario(scenario, auto_generated_file_adapter, engine)
